/**
 * Green Dam Youth Escort 2026 — content script.
 *
 * Hides individual elements whose text matches the parent's word lists, and
 * images the local classifier scores above threshold. It judges content, not
 * domains: a forum thread with one bad post loses that post, not the site.
 *
 * The decision rules live in Python (`host/extension/__init__.py`) and are
 * tested there. This file implements the same rules and loads the same
 * configuration, so the two cannot drift silently: `config.json` is generated by
 * `host/extension`, not hand-written.
 *
 * Three rules this file follows, each of which is a decision:
 *
 * 1. **Hide, do not navigate.** Blocking an element leaves the page usable.
 * 2. **Never hide the page's own chrome.** Navigation, comment boxes and controls
 *    stay, because hiding them makes the site look broken.
 * 3. **Say what happened, in place.** A hidden element is replaced by a short
 *    notice. An element that vanishes silently looks like a rendering bug, and
 *    the child learns that reloading fixes it.
 *
 * Privacy: this script never sends text anywhere. It sends image *bytes* to the
 * local service on 127.0.0.1 only, and only when the image passes the URL test.
 * Nothing leaves the machine.
 */
"use strict";

/** @type {object|null} */
let CONFIG = null;

/** Elements already handled, so a mutation does not re-hide them. */
const handled = new WeakSet();

/** Image URLs already scored, so the same picture is not sent twice. */
const scoredImages = new Map();

/** Set once the extension has been disabled by the parent, to stop all work. */
let disabled = false;

/**
 * Load the configuration generated by the Python side.
 *
 * A missing config is not fatal: the extension simply does nothing and says so
 * in the console. Failing loudly on every page would be worse than being inert.
 */
async function loadConfig() {
  if (CONFIG) return CONFIG;
  try {
    const response = await fetch(chrome.runtime.getURL("config.json"));
    CONFIG = await response.json();
  } catch (error) {
    console.warn("[greendam] no config.json; the filter is inactive", error);
    CONFIG = { terms: [], hideText: false, hideImages: false };
  }
  return CONFIG;
}

/**
 * Decide whether `text` should be hidden. Mirrors `decide_text` in Python.
 *
 * Returns the matched term (for logging) or null.
 */
function matchText(text, config) {
  if (!config.hideText || !config.terms || config.terms.length === 0) return null;
  if (!text || text.length < 2) return null;
  if (text.length > config.maxTextLength) return null;

  const haystack = config.caseSensitive ? text : text.toLowerCase();
  for (const term of config.terms) {
    const needle = config.caseSensitive ? term : term.toLowerCase();
    if (needle && haystack.includes(needle)) return term;
  }
  return null;
}

/**
 * Decide what to do with an image URL. Mirrors `decide_image` in Python.
 *
 * Returns "score", "skip" or "ignore".
 */
function classifyImageUrl(url, config) {
  if (!url) return "ignore";
  if (!config.hideImages) return "skip";

  const lowered = url.toLowerCase();
  if (lowered.startsWith("data:")) return "skip";
  if (
    lowered.startsWith("chrome:") ||
    lowered.startsWith("about:") ||
    lowered.startsWith("moz-extension:")
  ) {
    return "ignore";
  }
  if (
    !lowered.startsWith("http://") &&
    !lowered.startsWith("https://") &&
    !lowered.startsWith("//")
  ) {
    return "ignore";
  }
  return "score";
}

/**
 * Whether an element is worth judging at all.
 *
 * Skipped: the page's chrome, anything invisible, and anything tiny. Judging
 * every inline span produces a hide decision for an element whose parent already
 * covers it, and rewriting the DOM for no gain makes pages janky.
 */
function shouldJudge(element) {
  if (!element || element.nodeType !== Node.ELEMENT_NODE) return false;
  if (handled.has(element)) return false;

  const tag = element.tagName.toLowerCase();
  if (CONFIG.skipTags.includes(tag)) return false;
  if (!CONFIG.textTags.includes(tag)) return false;

  // Invisible elements cannot be judged and must not be rewritten.
  const style = window.getComputedStyle(element);
  if (style.display === "none" || style.visibility === "hidden") return false;

  return true;
}

/**
 * Replace an element's content with a notice, leaving the element in place.
 *
 * The element itself is kept rather than removed, so the page's layout does not
 * reflow and the surrounding content stays where the reader expects it.
 */
function hideElement(element, reason) {
  const notice = document.createElement("div");
  notice.className = "greendam-blocked";
  notice.setAttribute("role", "note");
  notice.textContent = "此内容已被过滤";
  if (reason) notice.dataset.greendamReason = reason;

  // Inline styles rather than a stylesheet: a stylesheet would need to be
  // injected into every frame and could be overridden by the page's own CSS.
  notice.style.cssText = [
    "padding:8px 12px",
    "margin:4px 0",
    "border-left:3px solid #c00",
    "background:#f7f7f7",
    "color:#444",
    "font:inherit",
    "font-size:0.9em",
  ].join(";");

  element.replaceChildren(notice);
  handled.add(element);
}

/** Ask the local service to score one image; hide it when the score is high. */
async function scoreImage(imageElement, config) {
  const url = imageElement.currentSrc || imageElement.src;
  if (!url) return;
  if (scoredImages.has(url)) {
    if (scoredImages.get(url) === "hide") hideElement(imageElement, "image");
    return;
  }

  // Below 64px in either direction it is an icon or a tracking pixel; the model
  // costs 90 ms and would be wrong about it anyway.
  if (imageElement.naturalWidth < 64 || imageElement.naturalHeight < 64) {
    scoredImages.set(url, "keep");
    return;
  }

  try {
    const response = await fetch(url, { credentials: "omit" });
    if (!response.ok) return;
    const blob = await response.blob();
    if (!blob.type.startsWith("image/")) return;

    const scored = await chrome.runtime.sendMessage({
      type: "score-image",
      blob: await blob.arrayBuffer(),
      contentType: blob.type,
    });

    if (scored && typeof scored.score === "number") {
      const verdict = scored.score >= config.imageThreshold ? "hide" : "keep";
      scoredImages.set(url, verdict);
      if (verdict === "hide") hideElement(imageElement, "image");
    }
  } catch (error) {
    // A failed score is not a reason to hide. "Not looked at" must never be
    // reported as "clean", and it must certainly not be reported as "blocked".
    console.debug("[greendam] image not scored", error);
  }
}

/** Walk a subtree, judging text containers and images. */
function scan(root, config) {
  if (disabled) return;

  const elements = root.querySelectorAll
    ? root.querySelectorAll(config.textTags.concat(["img"]).join(","))
    : [];

  for (const element of elements) {
    if (handled.has(element)) continue;

    const tag = element.tagName.toLowerCase();
    if (tag === "img") {
      if (classifyImageUrl(element.currentSrc || element.src, config) === "score") {
        scoreImage(element, config);
      }
      continue;
    }

    if (!shouldJudge(element)) continue;

    // Only judge elements whose *own* text is the content. An element with
    // element children is a container; its children are judged separately, and
    // hiding the container would take innocent siblings with it.
    if (element.children.length > 0) continue;

    const matched = matchText(element.textContent || "", config);
    if (matched) hideElement(element, "text");
  }
}

/**
 * Observe the page for content added after load.
 *
 * SPA sites and infinite-scroll feeds add content continuously; a single scan at
 * document_idle would miss most of it. The observer is debounced because a busy
 * page produces thousands of mutations per second.
 */
function observe(config) {
  let pending = null;
  const observer = new MutationObserver((mutations) => {
    if (disabled) return;
    if (pending) return;
    pending = requestAnimationFrame(() => {
      pending = null;
      for (const mutation of mutations) {
        for (const node of mutation.addedNodes) {
          if (node.nodeType === Node.ELEMENT_NODE) scan(node, config);
        }
      }
    });
  });

  observer.observe(document.documentElement, {
    childList: true,
    subtree: true,
  });
}

/** Entry point. */
async function main() {
  const config = await loadConfig();
  if (disabled) return;

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => scan(document, config));
  } else {
    scan(document, config);
  }
  observe(config);

  // The parent can switch filtering off without reloading every tab.
  chrome.runtime.onMessage.addListener((message) => {
    if (message && message.type === "set-enabled") {
      disabled = !message.enabled;
    }
  });
}

main();
